import { mkdir, readdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";

import { CONFERENCES } from "../src/lib/conferences.ts";
import { CONFERENCE_ROUTE_DEFINITIONS, conferenceMenuPath } from "../src/lib/routes.ts";

const publicDir = "public";
const dataRootDir = path.join(publicDir, "ht");
const structuredDataDir = path.join(publicDir, "structured-data");
const SITE_ORIGIN = "https://info.defcon.org";
const generatedHeader =
  "<!-- This file is generated by scripts/generate-public-indexes.mjs from src/lib/conferences.ts. Do not edit by hand. -->";
const generatedTextNotice =
  "> Generated by scripts/generate-public-indexes.mjs from src/lib/conferences.ts. Do not edit by hand.";

const PUBLIC_CONFERENCE_ALIASES = [
  {
    slug: "dc34",
    canonicalSlug: "defcon34",
  },
];

const organizationBackedSiteMenuKeys = new Set([
  "communities",
  "contests",
  "departments",
  "exhibitors",
  "vendors",
  "villages",
]);

const primaryFiles = [
  ["manifest.json", "Manifest JSON"],
  ["conference.json", "Conference maps JSON"],
  ["views/scheduleDays.json", "Schedule runtime view JSON"],
  ["views/contentCards.json", "Content cards JSON"],
  ["views/peopleCards.json", "People cards JSON"],
  ["views/searchData.json", "Search index JSON"],
];

const humanPages = [
  ["", "home"],
  ["schedule", "Schedule"],
  ["people", "Speakers and people"],
  ["locations", "Locations"],
  ["villages", "Villages"],
  ["search", "Search"],
];

const siteMenuLabels = new Map([
  ["announcements", "announcements"],
  ["bookmarks", "bookmarks"],
  ["communities", "communities"],
  ["content", "content"],
  ["contests", "contests"],
  ["departments", "departments"],
  ["exhibitors", "exhibitors"],
  ["locations", "locations"],
  ["maps", "maps"],
  ["merch", "merch"],
  ["people", "speakers and people"],
  ["readme", "readme"],
  ["schedule", "schedule"],
  ["search", "search"],
  ["vendors", "vendors"],
  ["villages", "villages"],
]);

const collectionLabels = new Map([
  ["schedule", "Schedule"],
  ["search", "Search"],
]);

const conferenceRoutesByKey = new Map(
  CONFERENCE_ROUTE_DEFINITIONS.map((route) => [route.key, route]),
);

const labelOverrides = new Map([
  ["conference.json", "Conference maps JSON"],
  ["derived/tagIdsByLabel.json", "Tag IDs by label JSON"],
  ["views/announcementsList.json", "Announcements list JSON"],
  ["views/bookmarkSessionsById.json", "Bookmark session lookup JSON"],
  ["views/contentCards.json", "Content cards JSON"],
  ["views/documentsList.json", "Documents list JSON"],
  ["views/locationCards.json", "Location cards JSON"],
  ["views/organizationsCards.json", "Organization cards JSON"],
  ["views/peopleCards.json", "People cards JSON"],
  ["views/scheduleDays.json", "Schedule runtime view JSON"],
  ["views/searchData.json", "Search index JSON"],
  ["views/tagTypesBrowse.json", "Tag browse JSON"],
  ["details/content.json", "Content detail lookup JSON"],
  ["details/documents.json", "Document detail lookup JSON"],
  ["details/organizations.json", "Organization detail lookup JSON"],
  ["details/people.json", "People detail lookup JSON"],
  ["details/tags.json", "Tag detail lookup JSON"],
]);

const removedRuntimeDataPattern =
  /^(?:raw\/|entities\/|indexes\/|details\/(?:sessions|locations|content|documents|organizations|people|tags)\/)/;

function isPublishedRuntimeJson(relativePath) {
  return relativePath.endsWith(".json") && !removedRuntimeDataPattern.test(relativePath);
}

function escapeHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function escapeXml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

function routeHref(...segments) {
  const route = segments.filter(Boolean).join("/");

  return route ? `/${route}` : "/";
}

function isFileLikePath(pathname) {
  const lastSegment = pathname.split("/").filter(Boolean).at(-1) ?? "";
  return lastSegment.includes(".");
}

function addDirectorySlash(pathname) {
  if (pathname === "/" || pathname.endsWith("/") || isFileLikePath(pathname)) return pathname;
  return `${pathname}/`;
}

function humanRouteHref(conference, segment = "") {
  if (!segment) return conferenceMenuPath(conference);

  return addDirectorySlash(routeHref(conference.slug, segment));
}

function dataHref(conference, relativePath) {
  return `${conference.dataRoot}/${relativePath}`;
}

function absoluteUrl(pathname) {
  return `${SITE_ORIGIN}${pathname}`;
}

function markdownLink(label, href) {
  return `[${label}](${href})`;
}

function stableJson(data) {
  return `${JSON.stringify(data, null, 2)}\n`;
}

function titleCaseIdentifier(value) {
  return value
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[-_]/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function labelForFile(relativePath) {
  return (
    labelOverrides.get(relativePath) ??
    `${titleCaseIdentifier(path.basename(relativePath, ".json"))} JSON`
  );
}

function wrapText(text, indent, maxLineLength = 100) {
  const width = maxLineLength - indent.length;
  const words = text.split(" ");
  const lines = [];
  let line = "";

  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;

    if (candidate.length > width && line) {
      lines.push(`${indent}${line}`);
      line = word;
      continue;
    }

    line = candidate;
  }

  if (line) {
    lines.push(`${indent}${line}`);
  }

  return lines.join("\n");
}

function renderParagraph(text) {
  return `      <p>
${wrapText(text, "        ")}
      </p>`;
}

function renderAlternateLink(href) {
  const escapedHref = escapeHtml(href);
  const line = `    <link rel="alternate" type="application/json" href="${escapedHref}" />`;

  if (line.length <= 100) {
    return line;
  }

  return `    <link
      rel="alternate"
      type="application/json"
      href="${escapedHref}"
    />`;
}

async function listJsonFiles(directory, prefix = "") {
  let entries;
  try {
    entries = await readdir(directory, { withFileTypes: true });
  } catch (error) {
    if (error?.code === "ENOENT") return [];
    throw error;
  }

  const files = [];

  for (const entry of entries) {
    const relativePath = prefix ? `${prefix}/${entry.name}` : entry.name;
    const fullPath = path.join(directory, entry.name);

    if (entry.isDirectory()) {
      if (!isPublishedRuntimeJson(`${relativePath}/placeholder.json`)) continue;
      files.push(...(await listJsonFiles(fullPath, relativePath)));
      continue;
    }

    if (entry.isFile() && isPublishedRuntimeJson(relativePath)) {
      files.push(relativePath);
    }
  }

  return files.toSorted((left, right) => left.localeCompare(right));
}

function renderLinks(items, makeHref) {
  return items
    .map(([relativePath, label]) => {
      const href = makeHref(relativePath);
      const line = `        <li><a href="${escapeHtml(href)}">${escapeHtml(label)}</a></li>`;

      if (line.length <= 100) {
        return line;
      }

      return `        <li>
          <a href="${escapeHtml(href)}">${escapeHtml(label)}</a>
        </li>`;
    })
    .join("\n");
}

function renderDataIndex(conference, jsonFiles) {
  const jsonFileSet = new Set(jsonFiles);
  const primaryItems = primaryFiles.filter(([relativePath]) => jsonFileSet.has(relativePath));
  const primaryPathSet = new Set(primaryItems.map(([relativePath]) => relativePath));
  const supportingItems = jsonFiles
    .filter((relativePath) => !primaryPathSet.has(relativePath))
    .map((relativePath) => [relativePath, labelForFile(relativePath)]);
  const title = `${conference.name} Runtime JSON`;
  const canonicalUrl = `${SITE_ORIGIN}/${conference.slug}/data/`;

  return `<!doctype html>
${generatedHeader}
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta
      name="description"
      content="Published ${escapeHtml(conference.name)} runtime JSON files used by the info.defcon.org web app."
    />
    <link rel="canonical" href="${escapeHtml(canonicalUrl)}" />
    <link rel="alternate" type="text/plain" href="/llms.txt" />
${primaryItems
  .map(([relativePath]) => renderAlternateLink(dataHref(conference, relativePath)))
  .join("\n")}
    <link rel="sitemap" type="application/xml" href="/sitemap.xml" />
    <title>${escapeHtml(title)}</title>
  </head>
  <body>
    <main>
      <h1>${escapeHtml(title)}</h1>

${renderParagraph(
  `${escapeHtml(conference.name)} runtime data is published as static JSON and fetched by the web app. These files mirror the route-level data contract used by the React application and may be replaced as conference information changes without rebuilding the site.`,
)}

      <h2>Primary Endpoints</h2>
      <ul>
${renderLinks(primaryItems, (relativePath) => dataHref(conference, relativePath))}
      </ul>

      <h2>Supporting Runtime Files</h2>
      <ul>
${renderLinks(supportingItems, (relativePath) => dataHref(conference, relativePath))}
      </ul>

      <h2>Structure</h2>
${renderParagraph(
  `Runtime JSON lives under <code>${escapeHtml(`${conference.dataRoot}/`)}</code>. View files are precomputed lists for route loading, aggregate detail lookup files are fetched lazily from route parameters and keyed by id, and derived files provide small lookup tables for the client UI.`,
)}

      <h2>Human Pages</h2>
      <ul>
${renderLinks(
  humanPages.map(([segment, label]) => [segment, segment ? label : `${conference.name} home`]),
  (segment) => humanRouteHref(conference, segment),
)}
      </ul>
    </main>
  </body>
</html>
`;
}

function renderAliasIndex(conference) {
  const canonicalPath = routeHref(conference.slug, "data") + "/";
  const canonicalUrl = `${SITE_ORIGIN}${canonicalPath}`;
  const title = `${conference.name} runtime data guide moved`;

  return `<!doctype html>
${generatedHeader}
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta
      name="description"
      content="Compatibility page for the ${escapeHtml(conference.name)} runtime JSON guide."
    />
    <meta http-equiv="refresh" content="0; url=${escapeHtml(canonicalPath)}" />
    <link rel="canonical" href="${escapeHtml(canonicalUrl)}" />
    <title>${escapeHtml(title)}</title>
  </head>
  <body>
    <main>
      <h1>${escapeHtml(title)}</h1>
      <p><a href="${escapeHtml(canonicalPath)}">Open the ${escapeHtml(conference.name)} runtime JSON guide.</a></p>
    </main>
  </body>
</html>
`;
}

async function writeGeneratedFile(routeSlug, html) {
  const directory = path.join(publicDir, routeSlug, "data");

  await mkdir(directory, { recursive: true });
  await writeFile(path.join(directory, "index.html"), html, "utf8");
}

function hasOrganizationBackedSection(conference) {
  return conference.siteMenu.some((key) => organizationBackedSiteMenuKeys.has(key));
}

function renderLlmsJsonDataLinks(conference) {
  const lines = [
    `- ${markdownLink(
      `${conference.name} manifest`,
      absoluteUrl(dataHref(conference, "manifest.json")),
    )}`,
    `- ${markdownLink(
      `${conference.name} schedule data`,
      absoluteUrl(dataHref(conference, "views/scheduleDays.json")),
    )}`,
  ];

  if (conference.siteMenu.includes("content")) {
    lines.push(
      `- ${markdownLink(
        `${conference.name} content data`,
        absoluteUrl(dataHref(conference, "views/contentCards.json")),
      )}`,
    );
  }

  if (conference.siteMenu.includes("people")) {
    lines.push(
      `- ${markdownLink(
        `${conference.name} people data`,
        absoluteUrl(dataHref(conference, "views/peopleCards.json")),
      )}`,
    );
  }

  if (conference.siteMenu.includes("locations")) {
    lines.push(
      `- ${markdownLink(
        `${conference.name} location data`,
        absoluteUrl(dataHref(conference, "views/locationCards.json")),
      )}`,
    );
  }

  if (hasOrganizationBackedSection(conference)) {
    lines.push(
      `- ${markdownLink(
        `${conference.name} organization cards`,
        absoluteUrl(dataHref(conference, "views/organizationsCards.json")),
      )}`,
    );
  }

  lines.push(
    `- ${markdownLink(
      `${conference.name} search index`,
      absoluteUrl(dataHref(conference, "views/searchData.json")),
    )}`,
    `- ${markdownLink(
      `${conference.name} runtime JSON guide`,
      `${absoluteUrl(routeHref(conference.slug, "data"))}/`,
    )}`,
  );

  return lines.join("\n");
}

function renderLlmsHumanLinks(conference) {
  const lines = [
    `- ${markdownLink(conference.name, absoluteUrl(humanRouteHref(conference)))}`,
    `- ${markdownLink(
      `${conference.name} runtime JSON guide`,
      `${absoluteUrl(routeHref(conference.slug, "data"))}/`,
    )}`,
  ];

  for (const key of conference.siteMenu) {
    const label = siteMenuLabels.get(key);
    const route = conferenceRoutesByKey.get(key);

    if (!label || !route) {
      continue;
    }

    lines.push(
      `- ${markdownLink(
        `${conference.name} ${label}`,
        absoluteUrl(humanRouteHref(conference, route.staticSegment)),
      )}`,
    );
  }

  return lines.join("\n");
}

function renderLlmsAliases() {
  if (PUBLIC_CONFERENCE_ALIASES.length === 0) {
    return "";
  }

  return `## Aliases

${PUBLIC_CONFERENCE_ALIASES.map((alias) => {
  const conference = CONFERENCES[alias.canonicalSlug];

  if (!conference) {
    throw new Error(
      `Unknown canonical conference slug for alias ${alias.slug}: ${alias.canonicalSlug}`,
    );
  }

  return `- ${markdownLink(
    `${conference.name} runtime JSON guide alias`,
    `${absoluteUrl(routeHref(alias.slug, "data"))}/`,
  )} canonical: ${markdownLink(
    `${conference.name} runtime JSON guide`,
    `${absoluteUrl(routeHref(conference.slug, "data"))}/`,
  )}`;
}).join("\n")}`;
}

function renderLlmsTxt(conferences) {
  const aliasesSection = renderLlmsAliases();
  const sections = [
    `# info.defcon.org

${generatedTextNotice}

info.defcon.org is a DEF CON conference information site. It provides human pages for conference schedules, speakers, locations, villages, search, and related reference information.

The browser app fetches conference data from JSON at runtime. These JSON files are the route-level data used by the React application and may be replaced independently of a site rebuild.

## Runtime JSON Data

${conferences.map((conference) => renderLlmsJsonDataLinks(conference)).join("\n\n")}

## Human Pages

- ${markdownLink("Site home", absoluteUrl("/"))}
- ${markdownLink("Conferences", absoluteUrl("/conferences/"))}
${conferences.map((conference) => renderLlmsHumanLinks(conference)).join("\n")}`,
    aliasesSection,
    `## Discovery

- ${markdownLink("Sitemap", absoluteUrl("/sitemap.xml"))}
- ${markdownLink("Robots", absoluteUrl("/robots.txt"))}

Prefer the JSON endpoints above when mirroring the published JSON data. Human pages are client-rendered and may summarize or navigate the same data.`,
  ].filter(Boolean);

  return `${sections.join("\n\n")}\n`;
}

function renderWebsiteStructuredData() {
  return stableJson({
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": `${SITE_ORIGIN}/#website`,
    name: "info.defcon.org",
    url: `${SITE_ORIGIN}/`,
    description: "DEF CON schedules and conference information.",
  });
}

function getStructuredDataCollections(conference) {
  const collections = [];

  if (conference.schedulePath || conference.siteMenu.includes("schedule")) {
    collections.push("schedule");
  }

  if (conference.siteMenu.includes("search")) {
    collections.push("search");
  }

  return collections;
}

function renderCollectionStructuredData(conference, collection) {
  const collectionLabel = collectionLabels.get(collection) ?? titleCaseIdentifier(collection);
  const collectionUrl = absoluteUrl(humanRouteHref(conference, collection));
  const dataFeed =
    collection === "schedule"
      ? {
          name: `${conference.name} schedule data JSON`,
          contentUrl: absoluteUrl(dataHref(conference, "views/scheduleDays.json")),
        }
      : {
          name: `${conference.name} search index JSON`,
          contentUrl: absoluteUrl(dataHref(conference, "views/searchData.json")),
        };

  return stableJson({
    "@context": "https://schema.org",
    "@type": "CollectionPage",
    "@id": `${collectionUrl}#collection`,
    name: `${conference.name} ${collectionLabel}`,
    url: collectionUrl,
    description: `Client-rendered ${conference.name} ${collection} page backed by authoritative runtime JSON data.`,
    isPartOf: {
      "@id": `${SITE_ORIGIN}/#website`,
    },
    mainEntity: {
      "@type": "DataFeed",
      name: dataFeed.name,
      contentUrl: dataFeed.contentUrl,
      encodingFormat: "application/json",
    },
  });
}

async function writeStructuredDataFiles(conferences) {
  await rm(structuredDataDir, { force: true, recursive: true });
  await mkdir(structuredDataDir, { recursive: true });
  await writeFile(
    path.join(structuredDataDir, "website.json"),
    renderWebsiteStructuredData(),
    "utf8",
  );

  const generatedFiles = ["structured-data/website.json"];

  for (const conference of conferences) {
    for (const collection of getStructuredDataCollections(conference)) {
      const filename = `${conference.slug}-${collection}.collection.json`;
      await writeFile(
        path.join(structuredDataDir, filename),
        renderCollectionStructuredData(conference, collection),
        "utf8",
      );
      generatedFiles.push(`structured-data/${filename}`);
    }
  }

  return generatedFiles;
}

function sitemapUrl(pathname) {
  return `  <url>
    <loc>${escapeXml(absoluteUrl(pathname))}</loc>
  </url>`;
}

function sitemapConferencePaths(conference) {
  const paths = [humanRouteHref(conference)];

  for (const key of conference.siteMenu) {
    const route = conferenceRoutesByKey.get(key);

    if (!route || !route.staticSegment) {
      continue;
    }

    paths.push(humanRouteHref(conference, route.staticSegment));
  }

  paths.push(`${routeHref(conference.slug, "data")}/`);

  return paths;
}

function sitemapAliasPaths() {
  return PUBLIC_CONFERENCE_ALIASES.map((alias) => `${routeHref(alias.slug, "data")}/`);
}

function renderSitemapXml(conferences) {
  const paths = [
    "/",
    "/apps/",
    "/conferences/",
    ...conferences.flatMap((conference) => sitemapConferencePaths(conference)),
    ...sitemapAliasPaths(),
  ];

  return `<?xml version="1.0" encoding="UTF-8"?>
${generatedHeader}
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${paths.map((pathname) => sitemapUrl(pathname)).join("\n")}
</urlset>
`;
}

const generated = [];
const conferences = Object.values(CONFERENCES);

for (const conference of conferences) {
  const jsonFiles = await listJsonFiles(path.join(dataRootDir, conference.slug));

  await writeGeneratedFile(conference.slug, renderDataIndex(conference, jsonFiles));
  generated.push(`${conference.slug}/data/index.html`);
}

for (const alias of PUBLIC_CONFERENCE_ALIASES) {
  const conference = CONFERENCES[alias.canonicalSlug];

  if (!conference) {
    throw new Error(
      `Unknown canonical conference slug for alias ${alias.slug}: ${alias.canonicalSlug}`,
    );
  }

  await writeGeneratedFile(alias.slug, renderAliasIndex(conference));
  generated.push(`${alias.slug}/data/index.html`);
}

await writeFile(path.join(publicDir, "llms.txt"), renderLlmsTxt(conferences), "utf8");
generated.push("llms.txt");

await writeFile(path.join(publicDir, "sitemap.xml"), renderSitemapXml(conferences), "utf8");
generated.push("sitemap.xml");

generated.push(...(await writeStructuredDataFiles(conferences)));

console.log("Generated public indexes:");
for (const file of generated.toSorted((left, right) => left.localeCompare(right))) {
  console.log(`- public/${file}`);
}
